import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        k = int(line)
    except ValueError:
        return

    if k == 1:
        n = 2
        adj = [['N'] * n for _ in range(n)]
        adj[0][1] = 'Y'
        adj[1][0] = 'Y'
        print(n)
        for row in adj:
            print(''.join(row))
        return

    layers = []
    temp_k = k
    while temp_k > 1:
        count = 1
        while count * count <= temp_k:
            count += 1
        count -= 1
        layers.append(count)
        temp_k //= count
    if temp_k > 1:
        layers.append(temp_k)

    layers.reverse()

    total_nodes = 2
    node_idx = 1
    layer_nodes = []

    for size in layers:
        current_layer = []
        for _ in range(size):
            current_layer.append(total_nodes)
            total_nodes += 1
        layer_nodes.append(current_layer)

    n = total_nodes
    adj = [['N'] * n for _ in range(n)]

    prev_nodes = [0]
    for i, layer in enumerate(layer_nodes):
        for u in prev_nodes:
            for v in layer:
                adj[u][v] = 'Y'
                adj[v][u] = 'Y'
        prev_nodes = layer

    for u in prev_nodes:
        adj[u][1] = 'Y'
        adj[1][u] = 'Y'

    print(n)
    for row in adj:
        print(''.join(row))

if __name__ == "__main__":
    solve()
